return ['po-revision-date'=>'2024-04-12 01:51:16+0000','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','x-generator'=>'GlotPress/4.0.1','language'=>'uk_UA','project-id-version'=>'ASE Pro','messages'=>['&lt;body&gt;'=>'&lt;тіло&gt;;','&lt;footer&gt;'=>'&lt;нижній колонтитул&gt;','&lt;head&gt;'=>'&lt;голова&gt;;','(Default is \'secret\')'=>'(За замовчуванням - "секретно")','(Default is 160px)'=>'(За замовчуванням 160px)','(filtered from _MAX_ total entries)'=>'(відфільтровано з _MAX_ записів)','+ %s'=>'+ %s','1 minute'=>'1 хвилина','10 minutes'=>'10 хвилин','120 seconds'=>'120 секунд','15 seconds'=>'15 секунд','2 minutes'=>'2 хвилини','3 minutes'=>'3 хвилини','30 seconds'=>'30 секунд','45 seconds'=>'45 секунд','5 minutes'=>'5 хвилин','60 seconds'=>'60 секунд','90 seconds'=>'90 секунд','<div class="asenha-warning">This feature <strong>only works for/with the default WordPress login page</strong>. It does not support using custom login page you manually created with a page builder or with another plugin.<br /><br />It\'s also <strong>not yet compatible with two-factor authentication (2FA) methods</strong>. If you use a 2FA plugin, please use the change login URL feature bundled in that plugin, or use another plugin that is compatible with it.<br /><br />And obviously, to improve security, please <strong>use something other than \'login\'</strong> for the custom login slug.</div>'=>'<div class="asenha-warning">Ця функція <strong>працює лише зі стандартною сторінкою входу в WordPress</strong>. Вона не підтримує використання власної сторінки входу, яку ви створили вручну за допомогою конструктора сторінок або іншого плагіна.<br /><br />Вона також <strong>поки що не сумісна з методами двофакторної автентифікації (2FA</strong>). Якщо ви використовуєте плагін 2FA, будь ласка, скористайтеся функцією зміни URL-адреси входу, що входить до складу цього плагіна, або використовуйте інший плагін, сумісний з ним.<br /><br />І, очевидно, для підвищення безпеки, будь ласка, <strong>використовуйте щось інше, ніж "login</strong> ", для спеціального слагу для входу в систему.</div>','<span class="faded">(Default is 1 minute)</span>'=>'<span class="faded">(За замовчуванням 1 хвилина)</span>','<span class="faded">(Default is 15 seconds)</span>'=>'<span class="faded">(Початковий - 15 секунд)</span>','<span class="field-sublabel sublabel-wide">Host</span>'=>'<span class="field-sublabel sublabel-wide">Ведучий</span>','<span class="field-sublabel sublabel-wide">Password</span>'=>'<span class="field-sublabel sublabel-wide">Пароль</span>','<span class="field-sublabel sublabel-wide">Port</span>'=>'<span class="field-sublabel sublabel-wide">Порт</span>','<span class="field-sublabel sublabel-wide">Security</span>'=>'<span class="field-sublabel sublabel-wide">Безпека</span>','<span class="field-sublabel sublabel-wide">Send a test email to</span>'=>'<span class="field-sublabel sublabel-wide">Надішліть тестовий лист на адресу</span>','<span class="field-sublabel sublabel-wide">Sender email</span>'=>'<span class="field-sublabel sublabel-wide">Email відправника</span>','<span class="field-sublabel sublabel-wide">Sender name</span>'=>'<span class="field-sublabel sublabel-wide">Ім\'я відправника</span>','<span class="field-sublabel sublabel-wide">Username</span>'=>'<span class="field-sublabel sublabel-wide">Ім\'я користувача</span>','<strong>Code to insert after &lt;body&gt; with the priority of</strong>'=>'<strong>Код для вставки після &lt;body&gt; з пріоритетом</strong>','<strong>Code to insert before &lt;/head&gt; with the priority of</strong>'=>'<strong>Код для вставки перед &lt;/head&gt; з пріоритетом</strong>','<strong>Code to insert in footer section before &lt;/body&gt; with the priority of</strong>'=>'<strong>Код для вставки в розділ footer перед &lt;/body&gt; з пріоритетом</strong>','<strong>Error:</strong> Invalid email or incorrect password.'=>'<strong>Помилка:</strong> Невірний email або неправильний пароль.','<strong>Insert CSS with the priority of</strong>'=>'<strong>Вставте CSS з пріоритетом</strong>','<strong>Your ads.txt content:</strong>'=>'<strong>Ваш вміст ads.txt:</strong>','AVIF Support Status'=>'Статус підтримки AVIF','AVIF Upload'=>'Завантаження AVIF','Actions'=>'Дії','Activate'=>'Активувати','Active'=>'Активний','Add'=>'Додати','Add CSS / SCSS Snippet'=>'Додати фрагмент CSS / SCSS','Add CSS/SCSS code'=>'Додайте код CSS/SCSS','Add Child'=>'Додати дитину','Add Code Snippet'=>'Додати фрагмент коду','Add File'=>'Додати новий','Add HTML Snippet'=>'Додати HTML-фрагмент','Add HTML code'=>'Додати HTML-код','Add JS Snippet'=>'Додати JS-фрагмент','Add JS code'=>'Додайте JS-код','Add New %s'=>'Додати нову %s','Add New Field Group'=>'Додати новий набір полей','Add PHP Snippet'=>'Додати PHP-фрагмент','Add Row'=>'Додати рядок','Add Your Review'=>'Додати свій огляд','Add categories for the media library and enable drag-and-drop categorization of media items. Categories can then be used to filter media items during media insertion into content.'=>'Додайте категорії до медіатеки та увімкніть категоризацію медіафайлів за допомогою перетягування. Категорії можна використовувати для фільтрування медіафайлів під час вставки їх у вміст.','Add custom &lt;body&gt; class(es) on the singular view of some or all public post types. Compatible with classes already added using <a href="https://wordpress.org/plugins/wp-custom-body-class" target="_blank">Custom Body Class plugin</a>.'=>'Додавання кастомних класів &lt;body&gt; до деяких або всіх типів публічних дописів у єдиному поданні. Сумісний з класами, вже доданими за допомогою <a href="https://wordpress.org/plugins/wp-custom-body-class" target="_blank">плагіна Custom Body Class</a>.','Add custom CSS on all admin pages for all user roles.'=>'Додайте кастомний CSS на всіх сторінках адміністратора для всіх ролей користувачів.','Add custom CSS on all frontend pages for all user roles.'=>'Додайте кастомний CSS на всіх сторінках інтерфейсу для всіх ролей користувачів.','Admin'=>'Адміністратор','Admin Columns Manager'=>'Адміністратор колонок','Admin Interface'=>'Інтерфейс адміністратора','Admin Menu Organizer'=>'Органайзер меню адміністратора','Admin and Site Enhancements (ASE) Pro'=>'Адміністрування та вдосконалення сайту (ASE) Pro','Admin bar'=>'Панель адміністратора','After duplication, redirect to:'=>'Після дублювання перенаправте на:','After saving the settings above, check if everything is configured properly below.'=>'Після збереження налаштувань вище, перевірте, чи все налаштовано належним чином нижче.','All %s'=>'Всі %s','All Code Snippets'=>'Всі фрагменти коду','All Media'=>'Всі ЗМІ','All Types'=>'Всі типи','Allow Custom Navigation Menu Items to Open in New Tab'=>'Дозволити користувацькі пункти меню навігації відкривати на новій вкладці','Allow custom navigation menu items to have links that open in new browser tab via target="_blank" attribute. The rel="noopener noreferrer nofollow" attribute will also be added for enhanced security and SEO benefits.'=>'Дозвольте кастомним пунктам навігаційного меню мати посилання, які відкриваються в новій вкладці браузера через атрибут target="_blank". Атрибут rel="noopener noreferrer nofollow" також буде додано для підвищення безпеки та покращення SEO.','Allow some or all user roles to upload SVG files, which will then be sanitized to keep things secure.'=>'Дозвольте деяким або всім ролям користувачів завантажувати SVG-файли, які потім будуть очищені для забезпечення безпеки.','Allow visitors with the following IP addresses to view the site directly:'=>'Дозвольте відвідувачам з наступних IP-адрес переглядати сайт безпосередньо:','Also disable frontend block styles / CSS files for the selected post types.'=>'Також вимкніть стилі блоків інтерфейсу / CSS-файли для вибраних типів публікацій.','Also enable custom ordering for the following post type(s), which are non-hierarchical and does not support page attributes:'=>'Також увімкніть користувацьке замовлення для наступних типів дописів, які не є ієрархічними і не підтримують атрибути сторінок:','Also hide admin notices for non-administrators.'=>'Також приховуйте повідомлення адміністратора для не-адміністраторів.','Also show additional filter(s) for non-hierarchical taxonomies.'=>'Також показувати додаткові фільтри для неієрархічних таксономій.','Always hide for user role(s)'=>'Завжди приховувати ролі користувачів','Any'=>'Будь-який','As a file'=>'У вигляді файлу','Attachment ID'=>'Ідентифікатор вкладення','Attempts<br />Lockouts'=>'Спроби<br />Блокування','Audio'=>'Аудіо','Author Display Name'=>'Відображуване ім\'я автора','Author Email'=>'Автор електронної пошти','Author Login'=>'Логін автора','Author Meta Field'=>'Метаполе "Автор','Author Nice Name'=>'Автор Гарне ім\'я','Author URL'=>'URL Автора','Auto-Publish Posts with Missed Schedule'=>'Автоматична публікація дописів з пропущеним розкладом','Automatically obfuscate email addresses in post content.'=>'Автоматично приховувати адреси електронної пошти у вмісті повідомлень.','Background'=>'Фон','Button Label'=>'Напис кнопки','Bypass password protection with URL parameter'=>'Обхід парольного захисту за допомогою параметра URL','Bypass verification of SSL certificate. This would be insecure if mail is delivered across the internet but could help in certain local and/or containerized WordPress scenarios.'=>'Обійти перевірку SSL-сертифіката. Це буде небезпечно, якщо пошта доставляється через Інтернет, але може допомогти в певних локальних та/або контейнерних сценаріях WordPress.','CSS'=>'CSS','CSS, JS, HTML and PHP code snippets'=>'Фрагменти коду CSS, JS, HTML та PHP','Cancel'=>'Скасувати','Cannot delete %1$s, as it is not within %2$s.'=>'Неможливо видалити %1$s, оскільки він не входить до %2$s.','Cannot redeclare %s.'=>'Неможливо передекларувати %s.','Cannot redeclare class %s.'=>'Неможливо перевизначити клас %s.','Cannot redeclare function %s.'=>'Не вдається перевизначити функцію %s.','Cannot redeclare interface %s.'=>'Не вдається перевизначити інтерфейс %s.','Categorize %s items'=>'Категоризувати %s елементів','Categorize 1 item'=>'Категоризувати 1 товар','Categorized %s items'=>'Категоризовано %s товарів','Categorizing...'=>'Категоризація...','Category does not exist, so cannot be deleted'=>'Категорія не існує, тому не може бути видалена','Change Login URL'=>'Змінити URL-адресу для входу','Changes have been saved.'=>'Зміни збережено.','Checkbox'=>'Прапорець','Choices'=>'Варіанти','Clean Up Admin Bar'=>'Очищення панелі адміністратора','Clean up admin pages by moving notices into a separate panel easily accessible via the admin bar.'=>'Очистіть сторінки адміністратора, перемістивши сповіщення в окрему панель, легко доступну через панель адміністратора.','Clean up and speed up the dashboard by completely disabling some or all widgets. Disabled widgets won\'t load any assets nor show up under Screen Options.'=>'Очистіть і пришвидшіть роботу інформаційної панелі, повністю вимкнувши деякі або всі віджети. Вимкнені віджети не завантажуватимуть жодних ресурсів і не відображатимуться в параметрах екрана.','Close'=>'Закрити','Code Snippets'=>'Фрагменти коду','Code Snippets Editor'=>'Редактор фрагментів коду','Code Snippets Manager'=>'Менеджер фрагментів коду','Collapse'=>'Згорнути','Color'=>'Колір','Column Width'=>'Ширина стовпця','Completely disable core, theme and plugin updates and auto-updates. Will also disable update checks, notices and emails.'=>'Повністю вимкнути оновлення ядра, тем і плагінів, а також автоматичне оновлення. Також вимкне перевірки оновлень, сповіщення та електронні листи.','Content Duplication'=>'Дублювання контенту','Content Management'=>'Управління контентом','Content Order'=>'Порядок вмісту','Conveniently add and manage CSS, JS, HTML and PHP code snippets to modify your site\'s content, design, behaviour and functionalities'=>'Зручно додавайте та керуйте фрагментами коду CSS, JS, HTML і PHP, щоб змінювати вміст, дизайн, поведінку та функціональність вашого сайту','Conveniently register and edit custom post types and custom taxonomies. Enable the creation of custom field groups for your post types and options pages to store data for display on any part of your website.'=>'Зручно реєструйте та редагуйте кастомні типи дописів і кастомні таксономії. Увімкніть створення кастомних груп полів для ваших типів дописів і сторінок параметрів, щоб зберігати дані для відображення в будь-якій частині вашого веб-сайту.','Convert BMP, PNG and JPG uploads to WebP instead of JPG.'=>'Конвертувати завантаження BMP, PNG і JPG у формат WebP замість JPG.','Convert newlines to <br />'=>'Перетворити нові рядки на <br />','Could not create temporary folder at %s'=>'Не вдалося створити тимчасову папку за адресою %s','Curves'=>'Криві','Custom Admin CSS'=>'Користувацький адмінський CSS','Custom Admin Footer Text'=>'Користувацький текст нижнього колонтитула адміністратора','Custom Body Class'=>'Індивідуальний клас тіла','Custom CSS'=>'Користувацький CSS','Custom Code'=>'Custom Code','Custom Content Types'=>'Користувацькі типи вмісту','Custom Field Group'=>'Користувацька група полів','Custom Field Groups'=>'Користувацькі групи полів','Custom Frontend CSS'=>'Кастомний інтерфейсний CSS','Customize the order of the admin menu and optionally change menu item title or hide some items.'=>'Налаштуйте порядок меню адміністратора і за бажанням змініть назву пункту меню або приховайте деякі пункти.','Customize the text you see on the footer of wp-admin pages other than this ASE settings page.'=>'Налаштуйте текст, який ви бачите в нижньому колонтитулі сторінок wp-admin, окрім цієї сторінки налаштувань ASE.','Date'=>'Дата','Deactivate'=>'Деактивувати','Default'=>'За замовчуванням','Default Value'=>'Значення за замовчуванням','Default Value(s)'=>'Значення за замовчуванням','Default is 10. Larger number insert code closer to &lt;/body&gt;'=>'За замовчуванням 10. Більше число вставляє код ближче до &lt;/body&gt;','Default is 10. Larger number insert code closer to &lt;/head&gt;'=>'За замовчуванням 10. Більше число вставляє код ближче до &lt;/head&gt;','Default is 10. Larger number inserts CSS closer to &lt;/head&gt; and allows it to better override other CSS loaded earlier in &lt;head&gt;.'=>'Значення за замовчуванням - 10. Більше число вставляє CSS ближче до &lt;/head&gt; і дозволяє йому краще перевизначати інші CSS, завантажені раніше в &lt;head&gt;.','Default is 10. Smaller number insert code closer to &lt;body&gt;'=>'За замовчуванням 10. Менше число вставляє код ближче до &lt;тіла&gt;','Default is 82 from a range between 1 to 100. The higher the number, the higher the quality and the file size.'=>'За замовчуванням встановлено значення 82 з діапазону від 1 до 100. Чим більше число, тим вища якість і розмір файлу.','Default text is: <em>Thank you for creating with <a href="https://wordpress.org/">WordPress</a></em>.'=>'Текст за замовчуванням: <em>Дякуємо, що створюєте за допомогою <a href="https://wordpress.org/">WordPress</a></em>.','Default text is: <em>Version %s</em>'=>'Текст за замовчуванням: <em>Версія %s</em>','Delete'=>'Видалити','Description'=>'Опис','Disable'=>'Вимкнути','Disable <strong>block-based widgets settings screen</strong>. Restores the classic widgets settings screen when using a classic (non-block) theme. This has no effect on block themes.'=>'Вимкнути <strong>екран налаштувань блокових віджетів</strong>. Відновлює класичний екран налаштувань віджетів при використанні класичної (неблокової) теми. Це не впливає на блокові теми.','Disable <strong>emoji support for pages, posts and custom post types</strong> on the admin and frontend. The support is primarily useful for older browsers that do not have native support for it. Most modern browsers across different OSes and devices now have native support for it.'=>'Вимкніть <strong>підтримку емодзі для сторінок, дописів і кастомних типів до</strong> писів в адмінці та на фронтенді. Ця підтримка в першу чергу корисна для старих браузерів, які не мають вбудованої підтримки емодзі. Більшість сучасних браузерів на різних ОС і пристроях тепер мають вбудовану підтримку.','Disable <strong>jQuery Migrate</strong> script on the frontend, which should no longer be needed if your site uses modern theme and plugins.'=>'Вимкніть скрипт <strong>jQuery Migrate</strong> на фронтенді, який більше не потрібен, якщо ваш сайт використовує сучасні теми та плагіни.','Disable <strong>version number</strong> on static resource URLs referenced in &lt;head&gt;, which can disclose WordPress version number. Older versions(s) might contain unpatched security loophole(s). Applies to non-logged-in view of pages. This will also increase cacheability of static assets, but may have unintended consequences. Make sure you know what you are doing.'=>'Вимкніть <strong>номер версії</strong> на статичних URL-адресах ресурсів, на які посилаються в &lt;head&gt;, що може розкрити номер версії WordPress. Старіші версії можуть містити невиправлені уразливості. Стосується перегляду сторінок без входу в систему. Це також збільшить кешованість статичних ресурсів, але може мати непередбачувані наслідки. Переконайтеся, що ви знаєте, що робите.','Disable All Updates'=>'Вимкнути всі оновлення','Disable Comments'=>'Вимкнути коментарі','Disable Components'=>'Вимкнути компоненти','Disable Dashboard Widgets'=>'Вимкнути віджети інформаційної панелі','Disable Feeds'=>'Вимкнути канали','Disable Gutenberg'=>'Вимкнути Гутенберга','Disable REST API'=>'Вимкнути REST API','Disable REST API access for non-authenticated users and remove URL traces from &lt;head&gt;, HTTP headers and WP RSD endpoint.'=>'Вимкніть доступ до REST API для неавторизованих користувачів і видаліть трасування URL-адрес з &lt;head&gt;, HTTP-заголовків і кінцевої точки WP RSD.','Disable Smaller Components'=>'Вимкнути менші компоненти','Disable XML-RPC'=>'Вимкнути XML-RPC','Disable all RSS, Atom and RDF feeds. This includes feeds for posts, categories, tags, comments, authors and search. Also removes traces of feed URLs from &lt;head&gt;.'=>'Вимкнути всі RSS, Atom і RDF-канали. Сюди входять стрічки для постів, категорій, тегів, коментарів, авторів і пошуку. Також видаляє сліди URL-адрес стрічок з &lt;head&gt;.','Disable comments for some or all public post types. When disabled, existing comments will also be hidden on the frontend.'=>'Вимкнути коментарі для деяких або всіх типів публічних дописів. Якщо вимкнено, існуючі коментарі також будуть приховані на інтерфейсі.','Disable except on'=>'Вимкнути за винятком','Disable loading of <strong>Dashicons CSS and JS files</strong> on the front-end for public site visitors. This might break the layout or design of custom forms, including custom login forms, if they depend on Dashicons. Make sure to check those forms after disabling.'=>'Вимкнути завантаження <strong>CSS та JS файлів Dashicons</strong> на фронтенді для відвідувачів загальнодоступного сайту. Це може порушити макет або дизайн кастомних форм, включаючи кастомні форми входу, якщо вони залежать від Dashicons. Не забудьте перевірити ці форми після вимкнення.','Disable only on'=>'Вимкнути тільки на','Disable the <strong>Really Simple Discovery (RSD) &lt;link&gt; tag</strong> in &lt;head&gt;. It\'s not needed if your site is not using pingback or remote (XML-RPC) client to manage posts.'=>'Вимкніть <strong>тег Really Simple Discovery (RSD) &lt;link&gt;</strong> в &lt;head&gt;. Він не потрібен, якщо ваш сайт не використовує пінгбек або віддалений (XML-RPC) клієнт для керування публікаціями.','Disable the <strong>Windows Live Writer (WLW) manifest &lt;link&gt; tag</strong> in &lt;head&gt;. The WLW app was discontinued in 2017.'=>'Вимкніть <strong>тег &lt;link&gt; маніфесту Windows Live Writer (WLW</strong> ) у &lt;head&gt;. Додаток WLW було припинено у 2017 році.','Disable the <strong>generator &lt;meta&gt; tag</strong> in &lt;head&gt;, which discloses the WordPress version number. Older versions(s) might contain unpatched security loophole(s).'=>'Вимкніть <strong>тег генератора &lt;meta&gt;</strong> в &lt;head&gt;, який розкриває номер версії WordPress. Старіші версії можуть містити невиправлені уразливості.','Disable the default <strong>WordPress shortlink &lt;link&gt; tag</strong> in &lt;head&gt;. Ignored by search engines and has minimal practical use case. Usually, a dedicated shortlink plugin or service is preferred that allows for nice names in the short links and tracking of clicks when sharing the link on social media.'=>'Вимкніть стандартний <strong>тег короткого посилання WordPress &lt;link&gt;</strong> в &lt;head&gt;. Ігнорується пошуковими системами і має мінімальну практичну користь. Зазвичай, краще використовувати спеціальний плагін або сервіс, який дозволяє створювати гарні назви для коротких посилань і відстежувати кліки, коли ви ділитеся посиланням у соціальних мережах.','Dismiss'=>'Відхилити','Display Active Plugins First'=>'Спочатку показувати активні плагіни','Display Settings'=>'Налаштування відображення','Display System Summary'=>'Короткий огляд системи відображення','Display a panel showing and linking to all available sizes when viewing an image in the media library. Especially useful to quickly get the URL of a particular image size.'=>'Відображати панель з посиланнями на всі доступні розміри під час перегляду зображення у медіатеці. Особливо корисно для швидкого отримання URL-адреси зображення певного розміру.','Display active / activated plugins at the top of the Installed Plugins list. Useful when your site has many deactivated plugins for testing or development purposes.'=>'Відображати активні/активовані плагіни у верхній частині списку встановлених плагінів. Корисно, коли на вашому сайті є багато деактивованих плагінів з метою тестування або розробки.','Do more with <a href="https://www.wpase.com/upgrade-ndg-btm" target="_blank">ASE Pro</a>. Lifetime deal (LTD) <a href="https://www.wpase.com/upgrade-ndg-btm-prc" target="_blank">available</a>.'=>'Робіть більше з <a href="https://www.wpase.com/upgrade-ndg-btm" target="_blank">ASE Pro</a>. <a href="https://www.wpase.com/upgrade-ndg-btm-prc" target="_blank">Доступна</a> довічна угода (LTD).','Docs'=>'Документи','Documentation'=>'Документація','Drag and drop menu items to the desired position. Optionally change 3rd party plugin/theme\'s menu item titles or hide some items until toggled by clicking "Show All" at the bottom of the admin menu.'=>'Перетягніть пункти меню в потрібне місце. За бажанням ви можете змінити заголовки пунктів меню сторонніх плагінів/тем або приховати деякі пункти, натиснувши кнопку "Показати все" внизу меню адміністратора.','Drag and drop menu items to the desired position. Optionally change 3rd party plugin/theme\'s menu item titles or hide some items until toggled by clicking "Show All" at the bottom of the admin menu. You can also choose to always hide menu items for all or some user roles.'=>'Перетягніть пункти меню в потрібне місце. За бажанням ви можете змінити заголовки пунктів меню сторонніх плагінів/тем або приховати деякі пункти, натиснувши кнопку "Показати все" внизу меню адміністратора. Ви також можете завжди приховувати пункти меню для всіх або деяких ролей користувачів.','Easily edit and validate your <a href="/ads.txt" target="_blank">ads.txt</a> and <a href="/app-ads.txt" target="_blank">app-ads.txt</a> content.'=>'Легко редагуйте та перевіряйте вміст ваших <a href="/ads.txt" target="_blank">ads.txt</a> та <a href="/app-ads.txt" target="_blank">app-ads.txt</a>.','Easily edit and validate your <a href="/robots.txt" target="_blank">robots.txt</a> content.'=>'Легко редагуйте та перевіряйте вміст <a href="/robots.txt" target="_blank">robots.txt</a>.','Easily enable enhancements and features that usually require multiple plugins.'=>'Легко вмикайте вдосконалення та функції, які зазвичай вимагають декількох плагінів.','Easily insert &lt;meta&gt;, &lt;link&gt;, &lt;script&gt; and &lt;style&gt; tags, Google Analytics, Tag Manager, AdSense, Ads Conversion and Optimize code, Facebook, TikTok and Twitter pixels, etc.'=>'Легко вставляйте теги &lt;meta&gt;, &lt;link&gt;, &lt;script&gt; і &lt;style&gt;, Google Analytics, Tag Manager, AdSense, Ads Conversion and Optimize code, пікселі Facebook, TikTok і Twitter тощо.','Easily replace any type of media file with a new one while retaining the existing media ID, publish date and file name. So, no existing links will break.'=>'Легко замінюйте будь-який тип медіафайлу на новий, зберігаючи існуючий ідентифікатор, дату публікації та ім\'я файлу. Таким чином, жодні існуючі посилання не будуть розірвані.','Edit'=>'Редагувати','Edit %s'=>'Редагувати %s','Edit CSS / SCSS Snippet'=>'Редагування фрагмента CSS / SCSS','Edit Code Snippet'=>'Редагувати фрагмент коду','Edit Field Group'=>'Редагування групи полів','Edit HTML Snippet'=>'Редагувати HTML-фрагмент','Edit JS Snippet'=>'Редагувати JS-фрагмент','Edit PHP Snippet'=>'Редагування фрагмента PHP','Edit screen'=>'Екран редагування','Edit screen publish section'=>'Редагування розділу публікації екрану','Email'=>'Email','Email Address Obfuscator'=>'Обфускатор адреси електронної пошти','Email Delivery'=>'Доставка електронною поштою','Email address only'=>'Тільки адреса електронної пошти','Enable assignment of multiple roles during user account creation and editing. This maybe useful for working with roles not defined in WordPress core, e.g. from e-commerce or LMS plugins.'=>'Увімкнути призначення декількох ролей під час створення та редагування облікового запису користувача. Це може бути корисно для роботи з ролями, не визначеними в ядрі WordPress, наприклад, з плагінів електронної комерції або LMS.','Enable custom ordering of terms from various "hierarchical" taxonomies. A new "Term Order" sub-menu will appear for enabled post type(s) with at least one such taxonomies. Terms listing and checkboxes in wp-admin will automatically use the custom order.'=>'Увімкнути користувацьке впорядкування термінів з різних "ієрархічних" таксономій. Нове підменю "Порядок термінів" з\'явиться для увімкнених типів дописів з принаймні однією такою таксономією. Список термінів і прапорці в wp-admin будуть автоматично використовувати цей порядок.','Enable custom ordering of various "hierarchical" content types or those supporting "page attributes". A new \'Order\' sub-menu will appear for enabled content type(s). The "All {Posts}" list page for enabled post types in wp-admin will automatically use the custom order.'=>'Увімкніть користувацьке впорядкування різних "ієрархічних" типів контенту або тих, що підтримують "атрибути сторінок". Для увімкнених типів контенту з\'явиться нове підменю "Порядок". На сторінці списку "Всі {Posts}" для увімкнених типів дописів у wp-admin автоматично використовуватиметься кастомний порядок.','Enable debug mode and output the debug info into WordPress debug.log file.'=>'Увімкніть режим налагодження і виводьте інформацію про налагодження у файл WordPress debug.log.','Enable except on:'=>'Увімкнути, крім увімкненого:','Enable log in, log out and dynamic log in/out menu item for addition to any menu.'=>'Увімкніть пункт меню входу, виходу та динамічного входу/виходу для додавання до будь-якого меню.','Enable one-click duplication of pages, posts and custom posts. The corresponding taxonomy terms and post meta will also be duplicated.'=>'Увімкніть дублювання сторінок, дописів і кастомних дописів в один клік. Відповідні терміни таксономії та метадані допису також будуть продубльовані.','Enable only for:'=>'Увімкнути тільки для:','Enable only on:'=>'Увімкнути:','Enable pages, posts and/or custom post types to have permalinks that point to external URLs. The rel="noopener noreferrer nofollow" attribute will also be added for enhanced security and SEO benefits. Compatible with links added using <a href="https://wordpress.org/plugins/page-links-to/" target="_blank">Page Links To</a>.'=>'Увімкніть для сторінок, дописів та/або кастомних типів дописів постійні посилання, які вказують на зовнішні URL-адреси. Атрибут rel="noopener noreferrer nofollow" також буде додано для підвищення безпеки та покращення SEO. Сумісний з посиланнями, доданими за допомогою <a href="https://wordpress.org/plugins/page-links-to/" target="_blank">Page Links To</a>.','Enable uploading <a href="https://www.smashingmagazine.com/2021/09/modern-image-formats-avif-webp/" target="_blank">AVIF</a> files in the Media Library. You can convert your existing PNG, JPG and GIF files using a tool like <a href="https://squoosh.app/" target="_blank">Squoosh</a>.'=>'Увімкніть завантаження файлів <a href="https://www.smashingmagazine.com/2021/09/modern-image-formats-avif-webp/" target="_blank">AVIF</a> у медіатеку. Ви можете конвертувати наявні файли PNG, JPG та GIF за допомогою такого інструменту, як <a href="https://squoosh.app/" target="_blank">Squoosh</a>.','Enable usage of any image from WordPress Media Library as user avatars.'=>'Увімкніть використання будь-якого зображення з медіатеки WordPress як аватарки користувача.','Enhance List Tables'=>'Покращення таблиць списків','Enhancements'=>'Покращення','Enter one IPv4 address per line'=>'Введіть одну IPv4-адресу в рядку','Everywhere'=>'Всюди','Expand'=>'Розкрити','Export ASE module settings as a JSON file to easily import into another site.'=>'Експортуйте налаштування модуля ASE у вигляді JSON-файлу, щоб легко імпортувати їх на інший сайт.','Export Settings'=>'Налаштування експорту','Export | Import'=>'Експорт | Імпорт','External Permalinks'=>'Зовнішні посилання','Failed Login Attempts Log'=>'Журнал невдалих спроб входу','Failed login attempts:'=>'Невдалі спроби входу:','Feedback'=>'Зворотній зв’язок','Field Label'=>'Назва поля','Field Name'=>'Назва поля','Field Type'=>'Тип поля','File / Media'=>'Файл / Медіа','File / Media Type'=>'Тип файлу / носія','File Extension'=>'Розширення файлу','File Extension and Type'=>'Розширення та тип файлу','File Name'=>'Назва файлу','File Name, Prettified'=>'Ім\'я файлу, препароване','File Size'=>'Розмір Файлу','File Type'=>'Тип файлу','File URL'=>'Силка на файл','Filter Code Type'=>'Тип коду фільтра','Find Out More'=>'Дізнатися більше','First'=>'Перший','For multiple values, separate with <code> |</code>, e.g. <code>value1 | value2</code>'=>'Для декількох значень <code> розділяйте</code> символом |, наприклад, <code>значення1 | значення2</code>','Force all links to external sites in post content, where <a href="https://developer.wordpress.org/reference/hooks/the_content/" target="_blank">the_content</a> hook is used, to open in new browser tab via target="_blank" attribute. The rel="noopener noreferrer nofollow" attribute will also be added for enhanced security and SEO benefits.'=>'Змусьте всі посилання на зовнішні сайти в контенті постів, де використовується <a href="https://developer.wordpress.org/reference/hooks/the_content/" target="_blank">хук_content</a>, відкриватися в новій вкладці браузера через атрибут target="_blank". Атрибут rel="noopener noreferrer nofollow" також буде додано для підвищення безпеки та покращення SEO.','Force the usage of the sender name/email defined above. It will override those set by other plugins.'=>'Примусити використовувати ім\'я/пошту відправника, визначену вище. Це перевизначить ті, що встановлені іншими плагінами.','Formatting'=>'Formatting','Frontend'=>'Інтерфейс','Full AVIF support requires that your server / hosting has <a href="https://php.watch/versions/8.1/gd-avif" target="_blank">GD extension</a> compiled with AVIF support in PHP 8.1 or greater, or, <a href="https://avif.io/blog/tutorials/imagemagick/" target="_blank">ImageMagick 7.0.25 or greater</a> installed. Without either, you can still upload AVIF files but without auto-generation of the smaller thumbnail sizes. A majority of <a href="https://avif.io/blog/articles/avif-browser-support/" target="_blank">modern desktop and mobile browsers</a> support the display of AVIF files.'=>'Повна підтримка AVIF вимагає, щоб на вашому сервері/хостингу було встановлено <a href="https://php.watch/versions/8.1/gd-avif" target="_blank">розширення GD</a>, скомпільоване з підтримкою AVIF в PHP 8.1 або новішої версії, або <a href="https://avif.io/blog/tutorials/imagemagick/" target="_blank">ImageMagick 7.0.25</a> або новішої версії. Без цього ви можете завантажувати AVIF-файли, але без автоматичної генерації мініатюр меншого розміру. Більшість <a href="https://avif.io/blog/articles/avif-browser-support/" target="_blank">сучасних десктопних і мобільних браузерів</a> підтримують відображення файлів AVIF.','Gallery'=>'Галерея','Get ASE Pro'=>'Отримайте ASE Pro','Give the admin menu more room to better accommodate wider items.'=>'Додайте в меню адміністратора більше місця, щоб краще розмістити ширші пункти.','HTML'=>'HTML','HTTP Code %s'=>'Код HTTP %s','Heading'=>'Заголовок','Heartbeat Control'=>'Контроль серцебиття','Help others discover ASE and maybe <a href="https://www.wpase.com/trnslt-plgnndg" target="_blank">translate</a> to your language.'=>'Допоможіть іншим відкрити ASE і, можливо, <a href="https://www.wpase.com/trnslt-plgnndg" target="_blank">перекладіть</a> на свою мову.','Hide'=>'Сховати','Hide Admin Bar'=>'Приховати панель адміністратора','Hide Admin Notices'=>'Приховати повідомлення адміністратора','Hide admin bar for all or some user roles.'=>'Приховати панель адміністратора для всіх або деяких ролей користувачів.','Hide admin bar on the frontend for all or some user roles.'=>'Приховати панель адміністратора у фронтенді для всіх або деяких ролей користувачів.','Hide the content editor'=>'Приховати редактор вмісту','Hide until toggled'=>'Приховувати до перемикання','Horizontal'=>'Горизонтальний','Hyperlink'=>'Гіперпосилання','I\'ve reviewed'=>'Я переглянув','I\'ve shared'=>'Я поділився','IP Address<br />Last Username'=>'IP-адреса<br />Ім\'я користувача','If set, the following SMTP service/account wil be used to deliver your emails.'=>'Якщо встановлено, для доставки ваших імейлів буде використовуватися наступна служба/обліковий запис SMTP.','If set, the following sender name/email overrides WordPress core defaults but can still be overridden by other plugins that enables custom sender name/email, e.g. form plugins.'=>'Якщо встановлено, наступне ім\'я відправника/адреса електронної пошти замінює значення за замовчуванням ядра WordPress, але може бути замінено іншими плагінами, які дозволяють використовувати власні імена/адреси відправників, наприклад, плагінами форм.','If something goes wrong</strong> and you need to regain access to your account as an administrator, please visit the following URL: <br /><strong>%s</strong><br /><br />If you use <strong>Ninja Firewall</strong>, please uncheck "Block attempts to gain administrative privileges" in the Firewall Policies settings before you try to view as a non-admin user role to <strong>prevent being locked out</strong> of your admin account.'=>'Якщо щось пішло не так</strong> і вам потрібно відновити доступ до вашого облікового запису як адміністратора, будь ласка, відвідайте наступну URL-адресу: <br /><strong>%s</strong><br /><br />Якщо ви використовуєте <strong>Ninja Firewall</strong>, будь ласка, зніміть прапорець "Блокувати спроби отримати адміністративні привілеї" в налаштуваннях Політики брандмауера перед тим, як спробувати переглянути сайт з правами не-адміністратора, щоб <strong>уникнути блокування</strong> вашого облікового запису адміністратора.','Image'=>'Зображення','Image Height'=>'Висота зображення','Image Preview Size'=>'Розмір попереднього перегляду зображення','Image Sizes Panel'=>'Панель розмірів зображень','Image Upload Control'=>'Контроль завантаження зображень','Image Width'=>'Зображення Ширина','Image Width and Height'=>'Ширина та висота зображення','Import ASE Settings'=>'Імпорт налаштувань ASE','Import ASE module settings you\'ve exported from another site as a JSON file.'=>'Імпортуйте налаштування ASE-модуля, експортовані з іншого сайту, у вигляді JSON-файлу.','Import Settings'=>'Налаштування імпорту','Imported'=>'Імпортується','Improve the usefulness of listing pages for various post types and taxonomies, media, comments and users by adding / removing columns and elements.'=>'Покращуйте корисність сторінок списку для різних типів дописів і таксономій, медіа, коментарів і користувачів, додаючи/видаляючи стовпці та елементи.','Inactive'=>'Неактивний','Inline'=>'Вбудовані','Insert'=>'Вставити','Insert &lt;head&gt;, &lt;body&gt; and &lt;footer&gt; Code'=>'Вставте код &lt;head&gt;, &lt;body&gt; та &lt;footer&gt','Install'=>'Встановити','Instructions'=>'Інструкція','Instructions for editors. Shown when submitting data.'=>'Інструкція для редакторів. Відображаються при подачі даних.','JS'=>'JS','Keep as is'=>'Зберегти як є','Last'=>'Остання','Last Attempt On'=>'Остання спроба','Last Login Column'=>'Стовпчик "Останній вхід','Layout'=>'Макет','Leave blank to skip this rule'=>'Залиште порожнім, щоб пропустити це правило','Left Side'=>'Лівий бік','Limit Login Attempts'=>'Обмеження спроб входу','Limit to'=>'Обмеження до','Limits'=>'Ліміти','Lines'=>'Позиції','Link Target'=>'Target посилання','Link Text'=>'Текст посилання','List view'=>'Подивитися список','List view post action row'=>'Рядок перегляду списку після дії','Load snippet'=>'Фрагмент завантаження','Local User Avatar'=>'Локальний аватар користувача','Log In | Log Out'=>'Увійдіть | Вийдіть','Log In/Out Menu'=>'Меню входу/виходу','Log when users on the site last logged in and display the date and time in the users list table.'=>'Записуйте час останнього входу користувачів на сайт і відображайте дату і час у таблиці списку користувачів.','Login ID Type'=>'Тип ідентифікатора для входу в систему','Login page'=>'Сторінка входу','Looks like some of these free enhancements have been useful for your site?'=>'Схоже, деякі з цих безкоштовних розширень виявилися корисними для вашого сайту?','Maintenance Mode'=>'Режим технічного обслуговування','Make sure to visit one of your frontend <a href="%1$s">pages</a> or <a href="%2$s">posts</a> while logged-in, to detect elements only visible in the frontend admin bar, and return here to see them on the list above.'=>'Обов\'язково відвідайте одну з ваших <a href="%1$s">сторінок</a> інтерфейсу або <a href="%2$s">публікацій</a> під час входу в систему, щоб виявити елементи, видимі лише в адмін-панелі інтерфейсу, і поверніться сюди, щоб побачити їх у списку вище.','Manage ads.txt and app-ads.txt'=>'Керування файлами ads.txt та app-ads.txt','Manage and organize columns in the admin listing for pages, posts and custom post types.'=>'Керуйте та впорядковуйте стовпці в списку адміністратора для сторінок, дописів і кастомних типів дописів.','Manage robots.txt'=>'Керування файлом robots.txt','Max height:'=>'Макс. висота:','Max width:'=>'Макс. ширина','Media Categories'=>'Медіа категорії','Media Categories Module: Tree View: Error'=>'Модуль категорій медіа: Деревоподібне представлення: Помилка','Media Categories Module: Tree View: Error: Could not load Plugin class <strong>%s</strong>'=>'Модуль категорій медіа: Деревоподібне представлення: Помилка: Не вдалося завантажити клас плагіна <strong>%s</strong>','Media Category'=>'Медіа категорія','Media Library Infinite Scrolling'=>'Медіатека Нескінченна прокрутка','Media Replacement'=>'Заміна носія','Medium (uncropped)'=>'Середній (необрізаний)','Message'=>'Повідомлення','Modified'=>'Змінений','Modify'=>'Модифікувати','Modify the interval of the WordPress heartbeat API or disable it on admin pages, post creation/edit screens and/or the frontend. This will help reduce CPU load on the server.'=>'Змініть інтервал серцебиття API WordPress або вимкніть його на сторінках адміністратора, екранах створення/редагування постів та/або у фронтенді. Це допоможе зменшити навантаження на процесор на сервері.','Multi-select?'=>'Мульти-вибір?','Multiple User Roles'=>'Кілька ролей користувачів','Never block the following IP addresses:'=>'Ніколи не блокуйте наступні IP-адреси:','New %s'=>'Новий %s','New Code Snippet'=>'Новий фрагмент коду','New Field'=>'Створити поле','New Field Group'=>'Нова польова група','New login URL:'=>'Нова URL-адреса для входу:','Next'=>'Наступне','No'=>'Ні','No Code Snippets found in Trash.'=>'У кошику не знайдено фрагментів коду.','No Code Snippets found.'=>'Фрагментів коду не знайдено.','No Field Groups found'=>'Польові групи не знайдено','No Field Groups found in Trash'=>'У кошику не знайдено жодної польової групи','No data available in table'=>'Даних у таблиці не знайдено','No matching records found'=>'Відповідних записів не знайдено','No settings data detected.'=>'Дані налаштувань не виявлено.','None'=>'Немає','None (bypass filters)'=>'Немає (обхідні фільтри)','Normal'=>'Нормальний','Not available'=>'Не доступний','Nothing to import'=>'Нічого імпортувати','Number'=>'Номер','Obfuscate Author Slugs'=>'Заплутані авторські помилки','Obfuscate email address to prevent spam bots from harvesting them, but make it readable like a regular email address for human visitors.'=>'Завуалюйте адресу електронної пошти, щоб спам-боти не змогли її зібрати, але зробіть її читабельною, як звичайну адресу електронної пошти для відвідувачів.','Obfuscate publicly exposed author page URLs that shows the user slugs / usernames, e.g. <em>sitename.com/author/username1/</em> into <em>sitename.com/author/a6r5b8ytu9gp34bv/</em>, and output 404 errors for the original URLs. Also obfuscates in /wp-json/wp/v2/users/ REST API endpoint.'=>'Замінює загальнодоступні URL-адреси сторінок авторів, які показують імена користувачів, наприклад, <em>sitename.com/author/username1/</em> на <em>sitename.com/author/a6r5b8ytu9gp34bv/</em>, і виводить 404 помилки для оригінальних URL-адрес. Також заплутує в кінцевій точці /wp-json/wp/v2/users/ REST API.','On admin pages'=>'На сторінках адміністратора','On post creation and edit screens'=>'На екранах створення та редагування дописів','On the backend:'=>'На сервері:','On the frontend'=>'На фронтенді','On the frontend:'=>'На зовнішній стороні:','On which part of the site?'=>'В якій частині сайту?','One (or more) of your fields had validation errors. More information is available below.'=>'В одному (або декількох) з ваших полів виникли помилки валідації. Більш детальна інформація доступна нижче.','One <code>value : label</code> per line, or just <code>label</code>. Use <code>{empty}</code> for an empty value.'=>'Одне <code>значення: мітка</code> на рядок або просто <code>мітка</code>. Використовуйте <code>{empty}</code> для порожнього значення.','Oops, something went wrong</span>.<br />Please double check your settings and the destination email address.'=>'Ой, щось пішло не так</span>.<br />Будь ласка, перевірте ваші налаштування та адресу електронної пошти призначення.','Open All External Links in New Tab'=>'Відкрийте всі зовнішні посилання в новій вкладці','Optimizations'=>'Оптимізації','Option Pages'=>'Додаткові сторінки','Options'=>'Опції','Options Pages'=>'Сторінки налаштувань','Or, help improve ASE by <a href="https://wordpress.org/support/plugin/admin-site-enhancements/" target="_blank">providing feedback</a>.'=>'Або допоможіть покращити ASE, <a href="https://wordpress.org/support/plugin/admin-site-enhancements/" target="_blank">надаючи зворотній зв’язок</a>.','Order'=>'Замовлення','Override the "Repeater Row” header text. You can also dynamically populate the row label with field values. If you have a text field named “first_name”, enter {first_name} to use the field value as the row label.'=>'Замінити текст заголовка "Рядок-повторювач". Ви також можете динамічно заповнювати мітку рядка значеннями полів. Якщо у вас є текстове поле з назвою "first_name", введіть {first_name}, щоб використовувати значення поля як мітку рядка.','PDF'=>'PDF','PHP'=>'PHP','PHP Array'=>'Масив PHP','Page Templates'=>'Шаблони сторінок','Page Title <span class="faded">(shown in the browser tab)</span>'=>'Назва сторінки <span class="faded">(відображається у вкладці браузера</span>)','Parent %s'=>'Батько %s','Parent %s:'=>'Батько %s:','Parent Code Snippet:'=>'Фрагмент батьківського коду:','Parse error: syntax error, unexpected end of snippet'=>'Помилка розбору: синтаксична помилка, неочікуваний кінець фрагмента','Parse error: syntax error, unexpected end of snippet.'=>'Помилка розбору: синтаксична помилка, неочікуваний кінець фрагмента.','Password Protection'=>'Захист паролем','Password-protect the entire site to hide the content from public view and search engine bots / crawlers. Logged-in administrators can still access the site as usual.'=>'Захистіть весь сайт паролем, щоб приховати його вміст від публічного перегляду та пошукових ботів/пошукових роботів. Увійшовши в систему, адміністратори можуть отримати доступ до сайту, як зазвичай.','Perform 301 (permanent) redirect to a URL of your choice'=>'Виконайте 301 (постійний) редирект на обрану вами URL-адресу','Perform 301 (permanent) redirect to the homepage for all 404 (not found) pages.'=>'Виконайте 301 (постійний) редирект на домашню сторінку для всіх 404 (не знайдено) сторінок.','Phone'=>'Телефон','Pick a single <code>value</code>'=>'Виберіть одне <code>значення</code>','Placement'=>'Розміщення','Please clear your cache</strong> after enabling or disabling maintenance mode. This ensures site visitors see either the maintenance page or the actual content of each page.'=>'Будь ласка, очистіть кеш</strong> після ввімкнення або вимкнення режиму технічного обслуговування. Це гарантує, що відвідувачі сайту бачитимуть або сторінку технічного обслуговування, або фактичний вміст кожної сторінки.','Please consider supporting ASE.'=>'Будь ласка, розгляньте можливість підтримати ASE.','Please find the relevant menu items under Settings.'=>'Будь ласка, знайдіть відповідні пункти меню в розділі Налаштування.','Please run the following command to make the directory writable'=>'Щоб зробити каталог доступним для запису, виконайте наступну команду','Please run the following commands in order to make the directory'=>'Будь ласка, виконайте наступні команди, щоб створити каталог','Position'=>'Позиція','Position on page'=>'Позиція на сторінці','Post Formats'=>'Формат запису','Post Types'=>'Типи допису','Posts'=>'Записи','Prevent bloating the database by limiting the number of revisions to keep for some or all post types supporting revisions.'=>'Запобігайте надмірному збільшенню бази даних, обмежуючи кількість редакцій, які слід зберігати для деяких або всіх типів записів, що підтримують редакції.','Prevent brute force attacks by limiting the number of failed login attempts allowed per IP address.'=>'Запобігайте атакам грубої сили, обмежуючи кількість невдалих спроб входу на одну IP-адресу.','Prevent smaller components from running or loading. Make the site more secure, load slightly faster and be more optimized for crawling by search engines.'=>'Запобігайте запуску або завантаженню менших компонентів. Зробіть сайт безпечнішим, трохи швидше завантажуватися і більш оптимізованим для сканування пошуковими системами.','Previous'=>'Попередній','Protect your site from brute force, DOS and DDOS attacks via <a href="https://kinsta.com/blog/xmlrpc-php/#what-is-xmlrpcphp" target="_blank">XML-RPC</a>. Also disables trackbacks and pingbacks.'=>'Захистіть свій сайт від грубої сили, DOS і DDOS-атак через <a href="https://kinsta.com/blog/xmlrpc-php/#what-is-xmlrpcphp" target="_blank">XML-RPC</a>. Також відключає трекбек і пінгбек.','Radio'=>'Радіо','Re-enable infinite scrolling in the grid view of the media library. Useful for scrolling through a large library.'=>'Увімкнути нескінченну прокрутку в сітковому поданні медіатеки. Корисно для прокручування великої бібліотеки.','Redirect 404'=>'Перенаправлення 404','Redirect 404 to Homepage'=>'Перенаправлення 404 на домашню сторінку','Redirect After Login'=>'Перенаправлення після входу','Redirect After Logout'=>'Перенаправлення після виходу з системи','Redirect default URLs to:'=>'Перенаправлення стандартних URL-адрес на:','Redirect to:'=>'Перенаправлення на:','Relationship'=>'Відносини','Remove'=>'Видалити','Remove \'Howdy\''=>'Видалити "Привіт','Remove WordPress logo/menu'=>'Видалити логотип/меню WordPress','Remove comments column'=>'Видалити колонку коментарів','Remove comments counter/link'=>'Видалити лічильник коментарів/посилання','Remove customize menu'=>'Видалити меню налаштувань','Remove extra elements listed below, which most likely come from your theme or plugins.'=>'Видаліть зайві елементи, перелічені нижче, які, найімовірніше, походять з вашої теми або плагінів.','Remove new content menu'=>'Видалити нове меню вмісту','Remove tags column (for posts)'=>'Видалити колонку тегів (для дописів)','Remove the Help tab and drawer'=>'Видаліть вкладку "Довідка" та панель','Remove updates counter/link'=>'Видалити лічильник/посилання на оновлення','Remove various elements from the admin bar.'=>'Видаліть різні елементи з панелі адміністратора.','Render this field with Select2'=>'Відобразити це поле за допомогою Select2','Repeater'=>'Повторювальне поле','Repeater Row'=>'Ряд повторювачів','Reset Menu'=>'Меню скидання налаштувань','Resize newly uploaded, large images to a smaller dimension and delete originally uploaded files. BMPs and non-transparent PNGs will be converted to JPGs and resized.'=>'Зменшити розмір нещодавно завантажених великих зображень до меншого розміру і видалити завантажені файли. BMP і непрозорі PNG-файли будуть перетворені в JPG і змінені в розмірах.','Restrict login ID to username or email address only.'=>'Обмежте ідентифікатор входу лише іменем користувача або адресою електронної пошти.','Return Value'=>'Значення, що повертається','Review'=>'Відгук','Revisions Control'=>'Контроль редакцій','Right Side'=>'Права сторона','Row Display'=>'Відображення рядків','Row Label'=>'Мітка рядка','SSL'=>'SSL','SVG Upload'=>'Завантаження SVG','Save Changes'=>'Зберегти зміни','Search %s'=>'Пошук %s','Search Code Snippets'=>'Фрагменти коду пошуку','Search Engines Visibility Status'=>'Статус видимості в пошукових системах','Search Field Groups'=>'Групи полів пошуку','Search terms'=>'Пошук термінів','Search users'=>'Пошук користувачів','Search...'=>'Пошук...','Search:'=>'Пошук:','Security'=>'Безпека','Select'=>'Вибрати','Select Profile Picture'=>'Виберіть зображення профілю','Select an Image'=>'Виберіть зображення','Send Now'=>'Надіслати Зараз','Sending test email...'=>'Відправлення тестового листа...','Set custom redirect URL for all or some user roles after login.'=>'Встановіть власну URL-адресу перенаправлення для всіх або деяких ролей користувачів після входу в систему.','Set custom redirect URL for all or some user roles after logout.'=>'Встановіть власну URL-адресу перенаправлення для всіх або деяких ролей користувачів після виходу з системи.','Set custom sender name and email. Optionally use external SMTP service to ensure notification and transactional emails from your site are being delivered to inboxes.'=>'Встановіть власне ім\'я відправника та адресу електронної пошти. За бажанням використовуйте зовнішній SMTP-сервіс, щоб забезпечити доставку сповіщень і транзакційних листів з вашого сайту до вхідних скриньок.','Set interval to once every'=>'Встановіть інтервал один раз на','Set the password:'=>'Встановіть пароль:','Set width to'=>'Встановіть ширину на','Settings saved.'=>'Налаштування збережені.','Show ID column'=>'Показати стовпчик ID','Show ID in action rows along with links for Edit, View, etc.'=>'Показувати ідентифікатор у рядках дій разом із посиланнями для редагування, перегляду тощо.','Show _MENU_ entries'=>'Показати _MENU_ записів','Show a customizable maintenance page on the frontend while performing a brief maintenance to your site. Logged-in administrators can still view the site as usual.'=>'Відображати настроювану сторінку технічного обслуговування у фронтенді під час виконання короткого технічного обслуговування вашого сайту. Увійшовши в систему, адміністратори можуть переглядати сайт у звичайному режимі.','Show additional filter(s) on list tables for hierarchical, custom taxonomies.'=>'Показати додаткові фільтри на таблицях переліків для ієрархічних, власних таксономій.','Show admin bar status when search engines are set to be discouraged from indexing the site. This is set through a "Search engine visibility" checkbox in Settings >> Reading.'=>'Показувати стан адмін-панелі та повідомлення адміністратора, коли пошуковим системам заборонено індексувати сайт. Це налаштовується за допомогою прапорця "Видимість для пошукових систем" в Налаштуваннях >> Читання.','Show duplication link on:'=>'Показати посилання для дублювання:','Show excerpt column'=>'Показати стовпчик з уривками','Show featured image column'=>'Показати стовпчик із зображеннями','Show file size column in media library'=>'Показати стовпчик розміру файлу в медіатеці','Show quick summary of the system the site is running on to admins, in the "At a Glance" dashboard widget. This includes the web server software, the PHP version, the database software and server IP address.'=>'Показуйте адміністраторам швидкий огляд системи, на якій працює сайт, у віджеті "З першого погляду" на інформаційній панелі. Сюди входить програмне забезпечення веб-сервера, версія PHP, програмне забезпечення бази даних та IP-адреса сервера.','Show the values by default'=>'Показати значення за замовчуванням','Showing 0 to 0 of 0 entries'=>'Показано від 0 до 0 із 0 записів','Showing _START_ to _END_ of _TOTAL_ entries'=>'Відображення _START_ до _END_ _TOTAL_ записів','Side'=>'Сторона','Site Identity on Login Page'=>'Ідентифікація сайту на сторінці входу','Skipped'=>'Пропущено','Snippet updated'=>'Оновлений фрагмент','Status'=>'Статус','Stripes'=>'Смуги','Submenu'=>'Підменю','Submit'=>'Відправити','Support'=>'Підтримка','TLS'=>'TLS','Tab'=>'Табуляція','Taxonomy Terms'=>'Терміни таксономії','Term'=>'Термін','Term IDs'=>'Ідентифікатори термінів','Term does not exist, so cannot be deleted'=>'Термін не існує, тому не може бути видалений','Terms Order'=>'Умови Замовлення','Test email was successfully processed</span>.<br />Please check the destination email\'s inbox to verify successful delivery.'=>'Тестовий лист було успішно оброблено</span>.<br />Будь ласка, перевірте поштову скриньку отримувача, щоб переконатися в успішній доставці.','Text'=>'Текст','Text Area'=>'Текстова область','Text Type'=>'Тип тексту','The %s directory could not be created'=>'Не вдалося створити каталог %s','The %s directory is not writable, therefore the code snippet files cannot be saved.'=>'Каталог %s є недоступним для запису, тому файли фрагментів коду не можуть бути збережені.','The Pro version of ASE is here! Lifetime Deal (LTD) available.'=>'Pro-версія ASE вже тут! Доступна довічна угода (LTD).','The code is active. Click to deactivate it'=>'Код активовано. Натисніть, щоб деактивувати його','The code is inactive. Click to activate it'=>'Код неактивний. Натисніть, щоб активувати його','The field group with the lowest order will appear first.'=>'Першою з\'явиться група полів з найнижчим порядком.','The field label that editors will see.'=>'Мітка поля, яку побачать редактори.','The field name is passed into get_cf() to retrieve values. Use only lowercase letters, numbers, and underscores.'=>'Ім\'я поля передається в get_cf() для отримання значень. Використовуйте лише малі літери, цифри та символи підкреслення.','The role(s) above have the <code>%s</code> capability required to view and access the menu item.'=>'Вищевказані ролі мають <code>%s</code> можливість, необхідну для перегляду та доступу до пункту меню.','The taxonomy_name or args[taxonomy_name] parameter must be included in the request.'=>'У запиті має бути вказано ім\'я_таксономії або параметр args[ім\'я_таксономії].','The text beside the checkbox'=>'Текст біля прапорця','This is a multi-select field'=>'Це поле з можливістю вибору','This is a required field'=>'Це необхідне поле','This site is undergoing maintenance for an extended period today. Thanks for your patience.'=>'Сьогодні цей сайт перебуває на тривалому технічному обслуговуванні. Дякуємо за ваше терпіння.','Thumbnail (cropped)'=>'Ескіз (обрізаний)','Title'=>'Назва','To exclude an image from conversion and resizing, append \'-nr\' suffix to the file name, e.g. bird-photo-4k-nr.jpg'=>'Щоб виключити зображення з конвертації та зміни розміру, додайте суфікс "-nr" до назви файлу, напр., bird-photo-4k-nr.jpg.','Toggle row visibility'=>'Перемикання видимості рядків','Tools'=>'Інструменти','Translate'=>'Переклад','Tree View'=>'Ієрархічний вигляд','Trigger publishing of scheduled posts of all types marked with "missed schedule", anytime the site is visited.'=>'Запускати публікацію запланованих постів усіх типів з позначкою "пропущено за розкладом" у будь-який час відвідування сайту.','Type'=>'Тип','URL'=>'URL','URL / oEmbed'=>'URL / oEmbed','Unable to delete %s'=>'Не вдалося видалити %s','Unauthorized.'=>'Несанкціоновано.','Uncategorized'=>'Без категорії','Under maintenance'=>'На технічному обслуговуванні','Update %s'=>'Оновити %s','Upgrade'=>'Оновити','Uploaded Date'=>'Дата завантаження','Uploaded Date and Time'=>'Завантажено дату та час','Uploaded Time'=>'Час завантаження','Use Selected Image'=>'Використати обране зображення','Use a shortcode like the following examples to display an email address on the frontend of your site: 
        		<ul>
        			<li><strong>[obfuscate email="john@example.com"]</strong> to display the email on it\'s own line</li>
        			<li><strong>[obfuscate email="john@example.com" display="inline"]</strong> to show the email inline</li>
        			<li><strong>[obfuscate email="john@example.com" display="inline" link="yes"]</strong> to show the email inline and linked with <strong>mailto:</strong></li>
        			<li><strong>[obfuscate email="john@example.com" display="inline" link="yes" subject="I\'m interested to learn about your services..."]</strong> to show the email inline and linked with <strong>mailto:</strong> with a pre-defined subject line.</li>
        			<li><strong>[obfuscate email="john@example.com" display="inline" link="yes" class="custom-class-name"]</strong> to show the email inline, linked with <strong>mailto:</strong> and has a custom CSS class to more easily customize the style.</li>
        		</ul>'=>'Використовуйте шорткод, як показано в наступних прикладах, щоб відобразити адресу електронної пошти на фронтенді вашого сайту: 
        		<ul>
        			<li><strong>[obfuscate email="john@example.com"]</strong> для відображення адреси в окремому рядку</li>
        			<li><strong>[obfuscate email="john@example.com" display="inline"]</strong> для відображення листа в рядку</li>
        			<li><strong>[obfuscate email="john@example.com" display="inline" link="yes"]</strong>, щоб показати лист в рядку і з прив\'язкою до <strong>mailto</strong>:</li>
        			<li><strong>[obfuscate email="john@example.com" display="inline" link="yes" subject="Мені цікаво дізнатися про ваші послуги..."]</strong>, щоб показати лист в рядку і пов\'язати з <strong>mailto:</strong> із заздалегідь визначеною темою.</li>
        			<li><strong>[obfuscate email="john@example.com" display="inline" link="yes" class="custom-class-name"]</strong> для відображення листа в рядку, з прив\'язкою до <strong>mailto:</strong> та кастомним CSS-класом для легшого налаштування стилю.</li>
        		</ul>','Use a shortcode like the following examples to display an email address on the frontend of your site: 
        		<ul>
        			<li><strong>[obfuscate email="john@example.com"]</strong> to display the email on it\'s own line</li>
        			<li><strong>[obfuscate email="john@example.com" display="inline"]</strong> to show the email inline</li>
        		</ul>'=>'Використовуйте шорткод, як показано в наступних прикладах, для відображення адреси електронної пошти на фронтенді вашого сайту: 
        		<ul>
        			<li><strong>[obfuscate email="john@example.com"]</strong> для відображення адреси в окремому рядку</li>
        			<li><strong>[obfuscate email="john@example.com" display="inline"]</strong> для відображення листа в рядку</li>
        		</ul>','Use as Profile Picture'=>'Використовувати як зображення профілю','Use custom order of terms on frontend query and display.'=>'Використовуйте власний порядок термінів у запиті та відображенні у фронтенді.','Use custom order on frontend query and display of enabled post types. You may need to manually set query order by <code>menu_order</code> in an <code>ascending</code> order.'=>'Використовуйте користувацький порядок у запиті до фронтенду та відображенні увімкнених типів дописів. Можливо, вам доведеться вручну встановити порядок запиту за допомогою <code>menu_order</code> за <code>зростанням</code>.','Use the site icon and URL to replace the default WordPress logo with link to wordpress.org on the login page. Go to the <a href="%s">customizer</a> to set or change your site icon.'=>'Використовуйте іконку сайту та URL-адресу, щоб замінити логотип WordPress за замовчуванням посиланням на wordpress.org на сторінці входу в систему. Перейдіть до <a href="%s">кастомізатора</a>, щоб встановити або змінити іконку сайту.','User'=>'Користувач','User Roles'=>'Ролі користувачів','Username'=>'Ім\'я користувача','Username only'=>'Тільки ім\'я користувача','Utilities'=>'Комунальні послуги','Validate with:'=>'Підтвердіть за допомогою:','Validation'=>'Перевірка','Vertical'=>'Вертикально','Video'=>'Відео','View Admin as Role'=>'Переглядайте адміністратора як роль.','View Code Snippet'=>'Переглянути фрагмент коду','View Field Group'=>'Переглянути групу полів','View admin pages and the site (logged-in) as one of the non-administrator user roles.'=>'Перегляд сторінок адміністратора та сайту (після входу в систему) як один з ролей користувача, який не є адміністратором.','WYSIWYG Editor'=>'WYSIWYG-редактор','We\'ll be back soon.'=>'Ми скоро повернемося.','WebP quality:'=>'Якість WebP:','Wider Admin Menu'=>'Розширене меню адміністратора','Write a quick, 5-star review for ASE'=>'Напишіть швидкий, п\'ятизірковий відгук про ASE.','Yes'=>'Так','You can also append <strong>?bypass=%1$s</strong> in the URL to bypass the password entry form. e.g. %2$s/?bypass=%3$s. This can be useful when you need to quickly share a dev site with another person, e.g. a client.'=>'Ви також можете додати <strong>?bypass=%1$s</strong> до URL-адреси, щоб обійти форму введення пароля, наприклад, %2$s/?bypass=%3$s. Це може бути корисно, коли вам потрібно швидко надати доступ до сайту розробника іншій особі, наприклад, клієнту.','add newAdd Code Snippet'=>'Додати фрагмент коду','add new on admin barCode Snippet'=>'Фрагмент коду','admin menuCode Snippets'=>'Фрагменти коду','e.g. 202.73.201.157'=>'наприклад, 202.73.201.157','e.g. backend'=>'наприклад, бекенд','e.g. my-account'=>'наприклад, мій обліковий запис','equals'=>'дорівнює','failed login attempts allowed before 15 minutes lockout'=>'невдалі спроби входу дозволені до 15-хвилинного блокування','for:'=>'для:','https://www.wpase.com/'=>'https://www.wpase.com/','https://www.wpase.com/author-uri'=>'https://www.wpase.com/author-uri','is not'=>'не є','lockout(s) will block further login attempts for 24 hours'=>'блокування заблокує подальші спроби входу на 24 години','pixels'=>'пікселів','pixels <span class="faded">(Default is 1920 pixels)</span>'=>'пікселі <span class="faded">(початковий розмір - 1920 px)</span>','pixels. <span class="faded">(Default is 1920 pixels)</span>'=>'пікселів. <span class="faded">(За замовчуванням 1920 пікселів)</span>','post type general nameCode Snippets'=>'Фрагменти коду','post type singular nameCode Snippet'=>'Фрагмент коду','revisions for:'=>'редакції для:','tag delimiter,'=>',','with AVIF support'=>'з підтримкою AVIF','without AVIF support'=>'без підтримки AVIF','wpase.com'=>'wpase.com']];
